-- Constructor method for the NotesObject class
function NotesObject:new()
    local notesObject = {}
    setmetatable(notesObject, self)
    self.__index = self
	
	self:getHostInformations()
	
	-- =====================================================================
	-- self.GROUPS
	-- PHONEM GROUPS TO EDIT
	-- key is an id
	-- label is the name of the group in the UI
	-- list is the phoneme list of the group, which are edited at once
	-- mouth and tension are the default parameters for the group
	-- =====================================================================

	self.controls = self:getControls()
	
	self:initializeControlsValues()
	self:setControlsCallback()
	
	self.statusTextValue = SV:create("WidgetValue")
	self.statusTextValue:setValue("")
	self.statusTextValue:setEnabled(false)

	self.infosTextValue = SV:create("WidgetValue")
	self.infosTextValue:setValue("")
	self.infosTextValue:setEnabled(false)
	
	self.clearButtonValue = SV:create("WidgetValue")
	self.adjustButtonValue = SV:create("WidgetValue")
	
	self:setButtonClearControlCallback()
	self:setButtonAdjustControlCallback()
	
	local infos = getClientInfo()

	self.infosToDisplay = ""
	if self.displayVersion then
		self.infosToDisplay = self.infosToDisplay .. SV:T("Version") .. ": " ..  infos.versionNumber
		if self.displayAuthor then
			self.infosToDisplay = self.infosToDisplay .. " - " .. SV:T("author") .. ": " .. infos.author
		end
	end
	-- self.infosToDisplay = self.infosToDisplay .. SV:T("minEditorVersion") .. ": " ..  infos.minEditorVersion
	self:addTextPanel(self.infosToDisplay)

	-- Register editor view selection callback
	self:registerEditorViewSelectionCallback()
	
	SV:refreshSidePanel()
	
    return self
end

-- Set button clear action control callback
function NotesObject:setButtonClearControlCallback()

	-- Button adjust action
	self.clearButtonValue:setValueChangeCallback(function()			
			self:getProject():newUndoRecord()
			self:clearAutomation()
		end
	)
end

-- Set button adjust action control callback
function NotesObject:setButtonAdjustControlCallback()

	-- Button adjust action
	self.adjustButtonValue:setValueChangeCallback(function()
			local selectedNotes = SV:getMainEditor():getSelection():getSelectedNotes()
			if #selectedNotes < 1 then
				SV:showMessageBox(SV:T("Error"), SV:T("Please select at least one note!"))
			else
				self:getProject():newUndoRecord()
				self:startAdjustment()
			end
		end
	)
end

-- Register editor view selection callback
function NotesObject:registerEditorViewSelectionCallback()
	
	-- Register selection callback to load parameters when selection changes
	SV:getMainEditor():getSelection():registerSelectionCallback(function(selectionType, isSelected)	
		self:onSelectionChanged()
	end)
	
	-- Register clear selection callback
	SV:getMainEditor():getSelection():registerClearCallback(function(selectionType)
		self:onSelectionChanged()
	end)
end

