-- Index of array
function NotesObject:indexOf(tbl, val)
    for i = 1, #tbl do
        if tbl[i] == val then
            return i
        end
    end
    return 0
end

-- Find a group in variable GROUPS
function NotesObject:findGroup(ph)
    for i = 1, #self.GROUPS do
        local g = self.GROUPS[i]
        if self:indexOf(g.list, ph) ~= 0 then
            return g
        end
    end
    return nil
end

-- Trim strings
function NotesObject:trim(s)
    if s == nil then return "" end
    s = tostring(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Split words
function NotesObject:splitWords(s)
    local out = {}
    for word in s:gmatch("%S+") do
        table.insert(out, word)
    end
    return out
end

-- All dashes in lyrics
function NotesObject:allDashes(tokens)
    if #tokens == 0 then return false end
    for i = 1, #tokens do
        if tokens[i] ~= "-" then
            return false
        end
    end
    return true
end


-- Get object properties (debug)
function NotesObject:getObjectProperties(obj, level)
	local result = ""
	local level = level or 0
	local maxLevel = 3
	level = level + 1
	
	for k, v in pairs(obj) do
		if obj[k] ~= nil then			
			local varType = type(v)
			
			if varType == "table" then
				result = result .. SV:T("Tb") .. " " .. self:trim(tostring(k)) .. ": "
				-- result = result .. " (" .. #v .. "): " -- size
				if level < maxLevel then
					result = result .. self:getObjectProperties(v, level)
				-- else
					-- result = result .. "\r"
				end
			else
				local data = self:trim(tostring(v))
				local dataText = data
				if varType == "string" then
					dataText = dataText .. " (" .. #v .. ") " -- size
				end
				local levelInfo = ""
				-- if level > 1 then
					-- levelInfo = "(Lv" .. level .. ") "
				-- end
				if  #data > 0 then
					result = result .. levelInfo .. self:trim(tostring(k)) .. "=" .. dataText
				else
					result = result .. levelInfo .. self:trim(tostring(k))
				end
				
				if varType == "boolean" then
					result = result .. " ".. "(" .. SV:T("b") .. ")"
				elseif varType == "string" then
					result = result .. " ".. "(" .. SV:T("s") .. ")"
				elseif varType == "number" then
					result = result .. " ".. "(" .. SV:T("n") .. ")"
				else
					result = result .. " " .. "(" .. varType .. ")"
				end
				 result = result .. "\r"
			end
		end
	end
	return result
end

-- On note selection change
function NotesObject:onSelectionChanged()
	local selection = SV:getMainEditor():getSelection()
	local selectedNotes = selection:getSelectedNotes()
	self:clearNoteInfoPanel()
	
	if #selectedNotes > 0 then
		self:addInfosTextPanel(SV:T("Selected notes:") .. " " .. #selectedNotes)
		local currentGroupRef = SV:getMainEditor():getCurrentGroup()
		local currentGroupNotes = currentGroupRef:getTarget()
		local timeOffset = currentGroupRef:getTimeOffset()
		local firstNote = selectedNotes[1]
		local lyrics = ""
		local sep = ""
		for i, note in ipairs(selectedNotes) do
			lyrics = lyrics .. sep .. note:getLyrics()
			sep = " "
		end
		self:addInfosTextPanel(SV:T("lyrics: ") .. lyrics)
		self:addInfosTextPanel(SV:T("Time: ") 
		.. self:secondsToClock(self:getTimeAxis():getSecondsFromBlick(firstNote:getOnset() + timeOffset)))
	else
		self:clearNoteInfoPanel()
	end
end

-- Clear display note info in panel
function NotesObject:clearNoteInfoPanel()
	self.infosTextValue:setValue("")
end

-- Write curve automation
function NotesObject:writeCurve(auto, segs, clearRange, ramp, reset)
    if #segs == 0 then return end

    local def = auto:getDefinition()
    local base = def.defaultValue
    local lo = def.range[1]
    local hi = def.range[2]

    for i = 1, #segs do
        segs[i].h = math.min(ramp / 2, (segs[i].e - segs[i].s) / 4)
        segs[i].v = math.max(lo, math.min(hi, segs[i].v))
    end

    local first = segs[1]
    local lastSeg = segs[#segs]
    if clearRange then
        auto:remove(self:mathRound(first.s - first.h), self:mathRound(lastSeg.e + lastSeg.h) + SV.QUARTER)
    end
	
	if not reset then
		for j = 1, #segs do
			local sg = segs[j]
			if j == 1 then
				auto:add(self:mathRound(sg.s - sg.h), base)
			else
				local pv = segs[j - 1]
				if sg.s - sg.h > pv.e + pv.h then
					auto:add(self:mathRound(pv.e + pv.h), base)
					auto:add(self:mathRound(sg.s - sg.h), base)
				end
			end
			auto:add(self:mathRound(sg.s + sg.h), sg.v)
			auto:add(self:mathRound(sg.e - sg.h), sg.v)
			if j == #segs then
				auto:add(self:mathRound(sg.e + sg.h), base)
			end
		end
	end
	
end

-- Get controls panel
function NotesObject:getControls()

	local controls = {}
	
	local paramKey = "clear_range"
	local clearRangeWg = {			-- Checkbox: enable clear previous points range
			value = SV:create("WidgetValue"),
			defaultValue = self.clearRange,
			paramKey = paramKey
		}
	controls[paramKey] = clearRangeWg
	
	for g = 1, #self.GROUPS do
		for ctrlType = 1, #self.controlTypes do
			local grp = self.GROUPS[g]
			local typeCtrl = self.controlTypes[ctrlType]
			
			local paramKey = typeCtrl .. grp.key
			local defaultValue = grp.value
			-- controlTypes = {"chk_", "sld_m_", "sld_t_"},
			if typeCtrl == "chk_" then
				defaultValue = grp.chkBoxValue
			end
			if typeCtrl == "sld_m_" then
				defaultValue = grp.mouth
			end
			if typeCtrl == "sld_t_" then
				defaultValue = grp.tension
			end
		
			controls[paramKey] = {
					value = SV:create("WidgetValue"),
					defaultValue = defaultValue,
					paramKey = paramKey
				}	
		end
	end
	
	-- self:show(self:getObjectProperties(controls))
	return controls
end

-- Initialize widget values
function NotesObject:initializeControlsValues()
	-- Initialize widget values
	for key, control in pairs(self.controls) do
		control.value:setValue(control.defaultValue)
	end
end

-- Set controls callback
function NotesObject:setControlsCallback()
	for key, control in pairs(self.controls) do
		control.value:setValueChangeCallback(function()
				-- self:addLogsInPanel()
				if control.paramKey == "clear_range" then
					self.clearRange = self.controls["clear_range"].value:getValue()
				end
			end
		)
	end
end

