							self.controls["sld_t_" .. grp.key].value, 
							SV:T("Tension"), 
							"%0.1f",
							-100, 100, 5
							)
					)
    end
end

-- Phonemes Of notes
function NotesObject:phonemesOf(note, all)
	local idx = note:getIndexInParent()
	local s = all[idx]
	if s == nil then
		s = all[idx + 1]
	end
	if type(s) ~= "string" or self:trim(s) == "" then
		s = note:getPhonemes()
	end
	s = self:trim(s)
	if s == "" then return {} end
	local raw = self:splitWords(s)
	local out = {}
	for i = 1, #raw do
		if raw[i] ~= "+" then
			table.insert(out, raw[i])
		end
	end
	return out
end

-- Add segment
function NotesObject:addSegment(segs, grp, s, e)
	if not grp or not self.controls["chk_" .. grp.key].value:getValue() then return end
	if e <= s then return end
	table.insert(segs, {s = s, e = e, grp = grp})
end

-- Trim before
function NotesObject:trimBefore(segs, cut)
	while #segs > 0 and segs[#segs].e > cut do
		local l = segs[#segs]
		if l.s >= cut then
			table.remove(segs)
		else
			l.e = cut
			break
		end
	end
end

-- lead starting phoneme
function NotesObject:leadStart(onset, nCons)
	local ms = math.min(self.LEAD_MAX_MS, nCons * self.LEAD_MS_PER_CONSONANT)
	local ok, sec = pcall(function()
		return self:getTimeAxis():getSecondsFromBlick(onset + offset)
	end)
	if ok and sec then
		local ok2, blick = pcall(function()
			return self:getTimeAxis():getBlickFromSeconds(sec - ms / 1000.0)
		end)
		if ok2 and blick then
			return blick - offset
		end
	end
	return onset - SV.QUARTER * ms / 500.0
end

-- Process adjustment
function NotesObject:process(all, groupRef, reset)
    local noteGroup = groupRef:getTarget()
	local selectedNotes = SV:getMainEditor():getSelection():getSelectedNotes()
    local mouth = noteGroup:getParameter("mouthOpening")
    local tension = noteGroup:getParameter("tension")
	local segs = {}
	local lastGroup = nil
	local ramp = SV.QUARTER * self.RAMP_QUARTERS
	
    -- Notes sorted by position
    local notes = {}
    for n = 1, #selectedNotes do
        table.insert(notes, selectedNotes[n])
    end
    table.sort(notes, function(x, y)
        return x:getOnset() < y:getOnset()
    end)

	local offset = 0
	pcall(function()
		offset = groupRef:getTimeOffset()
	end)

	for i = 1, #notes do
		local note = notes[i]
		local onset = note:getOnset()
		local dur = note:getDuration()
		local end_note = onset + dur

		local tokens = self:phonemesOf(note, all)
		local lyric = self:trim(note:getLyrics())

		if lyric == "-" or self:allDashes(tokens) then
			self:addSegment(segs, lastGroup, onset, end_note)
			goto continue_note
		end

		local durs = nil
		pcall(function()
			local attrs = note:getAttributes()
			durs = attrs and attrs.dur or nil
		end)

		local firstFull = -1
		for f0 = 1, #tokens do
			if self:findGroup(tokens[f0]) and self:indexOf(self.PRE_ONSET_GLIDES, tokens[f0]) == 0 then
				firstFull = f0
				break
			end
		end

		local vow = {}
		for k = 1, #tokens do
			local grp = self:findGroup(tokens[k])
			if grp then
				if firstFull ~= -1 and k < firstFull and self:indexOf(self.PRE_ONSET_GLIDES, tokens[k]) ~= 0 then
					-- skip
				else
					local w = 1
					if durs then
						local dVal = durs[k - 1] or durs[k]
						if type(dVal) == "number" then
							w = dVal
						end
					elseif self:indexOf(self.GLIDES, tokens[k]) ~= 0 then
						w = self.GLIDE_WEIGHT
					end
					if w < 0.01 then w = 0.01 end
					table.insert(vow, {k = k - 1, group = grp, w = w})
				end
			end
		end
		if #vow == 0 then goto continue_note end

		if vow[1].k > 0 then
			self:trimBefore(segs, self:leadStart(onset, vow[1].k) - ramp / 2)
		end

		local last = vow[#vow]
		lastGroup = last.group

		local tail = (last.k < #tokens - 1) and (self.CODA_SHARE * dur) or 0
		local spanEnd = end_note - tail

		local total = 0
		for v = 1, #vow do
			total = total + vow[v].w
		end

		local cursor = onset
		for q = 1, #vow do
			local len = (spanEnd - onset) * vow[q].w / total
			self:addSegment(segs, vow[q].group, self:mathRound(cursor), self:mathRound(cursor + len))
			cursor = cursor + len
		end

		::continue_note::
	end

	local mSegs = {}
	local tSegs = {}
	for z = 1, #segs do
		table.insert(mSegs, {s = segs[z].s, e = segs[z].e, v = self.controls["sld_m_" .. segs[z].grp.key].value:getValue()})
		table.insert(tSegs, {s = segs[z].s, e = segs[z].e, v = self.controls["sld_t_" .. segs[z].grp.key].value:getValue() / 100.0})
	end
	
	local clear = not not self.controls["clear_range"].value:getValue()

	local fs = {}
	for f = 1, #mSegs do
		local md = mouth:getDefinition()
		local raw = mSegs[f].v / 100.0
		local lo = md.range[1]
		local hi = md.range[2]
		local val = md.defaultValue +
			(raw >= 0 and (raw * (hi - md.defaultValue))
					  or (raw * (md.defaultValue - lo)))
		table.insert(fs, {s = mSegs[f].s, e = mSegs[f].e, v = val})
	end

	self:writeCurve(mouth, fs, clear, ramp, reset)
	self:writeCurve(tension, tSegs, clear, ramp, reset)
	
end

-- Clear automation
function NotesObject:clearAutomation()
    local groupRef = SV:getMainEditor():getCurrentGroup()
	
	local all = SV:getPhonemesForGroup(groupRef)
	local reset = true
	self:process(all, groupRef, reset)

end

-- Start adjustment
function NotesObject:startAdjustment()
    local groupRef = SV:getMainEditor():getCurrentGroup()
	
	local all = SV:getPhonemesForGroup(groupRef)
	local reset = false
	self:process(all, groupRef, reset)
end


-- Get panel section state
function NotesObject:getPanelSectionState()

	local errors = self:displayErrors()
	if #errors > 0 then
		self:addTextPanel(errors)
	end
	
	-- Get section data
	local section = self:getSection()

	return section
end

-- Initialize main internal object	
local notesObject = NotesObject:new()

-- Get panel section state called by Synthesizer V internal system
function getSidePanelSectionState()

	local section = notesObject:getPanelSectionState()

	return section
end